testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Veiculo, Carro } from './solution.mjs';

test('super inicializa os campos da classe mãe', () => {
  const carro = new Carro('Fiat', 2020, 4);
  assert.equal(carro.marca, 'Fiat');
  assert.equal(carro.ano, 2020);
  assert.equal(carro.portas, 4);
});

test('descricao combina a mãe com a filha via super', () => {
  const carro = new Carro('Fiat', 2020, 4);
  assert.equal(carro.descricao(), 'Veiculo: Fiat (2020) com 4 portas');
});

test('as validações da mãe valem para a filha', () => {
  assert.throws(() => new Carro('', 2020, 4));
  assert.throws(() => new Carro('Fiat', '2020', 4));
});

test('a filha valida os campos dela e a mãe continua intacta', () => {
  assert.throws(() => new Carro('Fiat', 2020, 0));
  assert.equal(new Veiculo('Bicicleta', 2019).descricao(), 'Veiculo: Bicicleta (2019)');
});

solutionCode:
// Veiculo é a classe mãe: marca e ano validados, descrição genérica.
export class Veiculo {
  constructor(marca, ano) {
    if (typeof marca !== 'string' || marca.trim() === '') {
      throw new Error('marca precisa ser um texto não vazio');
    }
    if (typeof ano !== 'number') {
      throw new Error('ano precisa ser um número');
    }
    this.marca = marca;
    this.ano = ano;
  }

  descricao() {
    return `Veiculo: ${this.marca} (${this.ano})`;
  }
}

// Carro É UM Veiculo: super() inicializa a parte da mãe, e a descrição
// reaproveita a da mãe com super.descricao() antes de acrescentar a própria.
export class Carro extends Veiculo {
  constructor(marca, ano, portas) {
    super(marca, ano); // PRIMEIRA linha: a mãe valida e guarda marca/ano
    if (typeof portas !== 'number' || portas < 1) {
      throw new Error('portas precisa ser um número maior ou igual a 1');
    }
    this.portas = portas;
  }

  descricao() {
    return `${super.descricao()} com ${this.portas} portas`;
  }
}
